WITH relations AS(SELECT oid,relname FROM pg_class WHERE oid IN(to_regclass('profiled_result_reports'),to_regclass('profiled_result_heads'),to_regclass('profiled_settlement_evaluations'),to_regclass('profiled_task_completions'),to_regclass('profiled_verified_releases'),to_regclass('review_subjects'),to_regclass('human_decision_finality'),to_regclass('human_decision_requests'),to_regclass('execution_attempts'),to_regclass('profiled_authority_hot'),to_regclass('agent_graph_operations'),to_regclass('agent_launch_bindings'),to_regclass('mailbox_operations'),to_regclass('source_transfers'))), objects AS (
 SELECT 'column' AS kind,a.attrelid::regclass::text||'.'||a.attname::text AS name,jsonb_build_object('type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'generated',a.attgenerated::text,'identity',a.attidentity::text,'default',pg_get_expr(d.adbin,d.adrelid)) AS body FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid IN(SELECT oid FROM relations) AND a.attnum>0 AND NOT a.attisdropped
 UNION ALL SELECT 'constraint',c.conrelid::regclass::text||'.'||c.conname,jsonb_build_object('kind',c.contype::text,'validated',c.convalidated,'deferrable',c.condeferrable,'deferred',c.condeferred,'definition',pg_get_constraintdef(c.oid,false)) FROM pg_constraint c WHERE c.conrelid IN(SELECT oid FROM relations) OR c.conname IN('profiled_phase_result_execution_key','profiled_phase_result_stop_key')
 UNION ALL SELECT 'index',i.indexrelid::regclass::text,jsonb_build_object('definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready,'live',i.indislive,'primary',i.indisprimary,'unique',i.indisunique,'immediate',i.indimmediate,'nulls_not_distinct',i.indnullsnotdistinct) FROM pg_index i WHERE i.indrelid IN(SELECT oid FROM relations) OR i.indexrelid IN(SELECT conindid FROM pg_constraint WHERE conname IN('profiled_phase_result_execution_key','profiled_phase_result_stop_key'))
 UNION ALL SELECT 'trigger',t.tgrelid::regclass::text||'.'||t.tgname,jsonb_build_object('definition',pg_get_triggerdef(t.oid,false),'enabled',t.tgenabled::text,'type',t.tgtype,'deferrable',t.tgdeferrable,'deferred',t.tginitdeferred) FROM pg_trigger t WHERE NOT t.tgisinternal AND (t.tgrelid IN(SELECT oid FROM relations) OR t.tgname='profiled_phase_qualified_release_guard')
 UNION ALL SELECT 'fk_internal',t.tgrelid::regclass::text||'.'||c.conname||'.'||p.proname||'.'||t.tgtype,jsonb_build_object('enabled',t.tgenabled::text,'type',t.tgtype,'deferrable',t.tgdeferrable,'deferred',t.tginitdeferred,'function',p.proname,'from',c.conrelid::regclass::text,'to',c.confrelid::regclass::text) FROM pg_trigger t JOIN pg_constraint c ON c.oid=t.tgconstraint JOIN pg_proc p ON p.oid=t.tgfoid WHERE t.tgisinternal AND c.contype='f' AND c.conrelid IN(SELECT oid FROM relations)
 UNION ALL SELECT 'function',p.proname,jsonb_build_object('body',p.prosrc,'args',pg_get_function_identity_arguments(p.oid),'returns',pg_get_function_result(p.oid),'language',l.lanname,'volatility',p.provolatile::text,'kind',p.prokind::text,'security_definer',p.prosecdef,'set',p.proretset,'strict',p.proisstrict,'parallel',p.proparallel::text,'config',p.proconfig) FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND (p.proname IN('profiled_result_origin_valid','profiled_phase_unqualified_result_guard','settlement_sender_key') OR p.oid IN(SELECT tgfoid FROM pg_trigger WHERE NOT tgisinternal AND tgrelid IN(SELECT oid FROM relations)))
) SELECT COALESCE(jsonb_agg(jsonb_build_object('kind',kind,'name',name,'body',body) ORDER BY kind,name),'[]'::JSONB) FROM objects
